  (W.EPI_ST || []).forEach(function (s) { (s.ws || []).forEach(function (f) { if (f.feat && W.EPI_FM[f.feat] && W.EPI_FM[f.feat].v) f.opts = W.EPI_FM[f.feat].v.slice(); }); });
