    kc.intake.stuckAt = where + (s.year != null && s.year !== "" ? " — لحظهٔ تاریخیِ " + yr(s.year) : "");
    kc.intake.what = "در شبیه‌سازِ «مسئله‌های بزرگ»، در " + where + " حرکتِ بعدی را پیدا نکردم.";
    kc.intake.seen = st && st.revealed ? "yes" : "no";
